import {api} from './api.js';
import {icons,garden} from './art.js';
import {calendarHeatmap} from './calendar.js';
import {taskPresets,rewardPresets,emojiBank,allEmojis,randomEncouragement,presetPickerHtml} from './presets.js';
import {quoteBubble} from './quotes.js';
const $=s=>document.querySelector(s);
const requestId=()=>{const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.leaf}</svg>`;
const btn=(text,action,cls='outline',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
let state=null,calendarData=null,page='today',filter='全部习惯',reviewFilter='pending',menu=false,selectedChild='',authMode='login',authRole='parent',loadingVersion=0;
let focusBeforeModal=null;
const parent=()=>state?.me.role==='parent';
const child=()=>state?.child;
const records=()=>state?.checkins||[];
const drafts=()=>records().filter(c=>c.status==='draft');
const pending=()=>records().filter(c=>c.status==='pending');
const money=()=>Number(child()?.balance||0);
const fmt=raw=>raw?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(raw.includes('T')?raw:raw.replace(' ','T')+'Z')):'—';
const todayRecord=id=>records().find(c=>c.task_id===id&&c.day===state.day);
const statusLabel=c=>({draft:'待提交',pending:'待家长审核',approved:c.auto_approved?'自动通过':'已通过',rejected:'未通过'}[c.status]);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('toast-show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('toast-show'),3800)}
async function refresh(){const version=++loadingVersion;try{const next=await api('/state'+(selectedChild?'?childId='+encodeURIComponent(selectedChild):''));if(version!==loadingVersion)return;state=next;selectedChild=next.child?.id||'';if(state.child){try{const cal=await api('/children/'+state.child.id+'/calendar?days=365');calendarData=cal;}catch{calendarData=null;}}else{calendarData=null;}render();}catch(e){if(e.status===401){state=null;selectedChild='';closeModal();renderAuth();}else throw e;}}
function renderAuth(error=''){++loadingVersion;state=null;$('#app').innerHTML=`<main class="auth-layout"><section class="auth-story"><div class="brand"><div class="brand-mark">${icon('leaf')}</div><div><strong>小小成长家</strong><small>LITTLE HABIT GARDEN</small></div></div><span class="eyebrow">GROW TOGETHER, EVERY DAY</span><h1>让每一份努力，<br>都被温柔看见。</h1><p>孩子认真坚持，家长用心鼓励。<br>一起把好习惯，种进每一天。</p><div class="auth-garden">${garden}</div><div class="auth-steps"><span>🌱 记录成长</span><span>🌳 家长审核</span><span>🎁 兑换心愿</span></div></section><section class="auth-side"><div class="auth-card"><div class="tabs"><button data-action="auth-tab" data-mode="login" class="${authMode==='login'?'selected':''}">登录</button><button data-action="auth-tab" data-mode="register" class="${authMode==='register'?'selected':''}">注册新账号</button></div><h2>${authMode==='login'?'欢迎回到成长花园':'开启一段成长旅程'}</h2><p class="field-help">${authMode==='login'?'登录一次，下次打开直接进入成长花园。':'请选择身份。家长与孩子使用各自账号，通过绑定码连接。'}</p><form id="auth-form">${authMode==='register'?`<div class="role-picker">${btn('🌳 我是家长','auth-role',authRole==='parent'?'selected':'','data-role="parent" type="button"')}${btn('🌱 我是孩子','auth-role',authRole==='child'?'selected':'','data-role="child" type="button"')}</div>${field('昵称','name','','text','required maxlength="40" autocomplete="nickname"')}`:''}${field('账号','username','','text','required minlength="3" maxlength="40" pattern="[A-Za-z0-9_]{3,40}" autocomplete="username" placeholder="3～40 位英文、数字或下划线"')}${field('密码','password','','password',`required minlength="8" maxlength="128" autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="至少 8 位"`)}${authMode==='register'?field('确认密码','repeat','','password','required minlength="8" maxlength="128" autocomplete="new-password"'):''}<div id="auth-error" class="error" role="alert">${esc(error)}</div>${submit(authMode==='login'?'进入成长花园':'创建'+(authRole==='parent'?'家长':'孩子')+'账号')}</form><div class="auth-note">北京时间 22:00 自动提交已完成内容<br>23:30 未审核的打卡自动通过</div></div></section></main>`;$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;const f=new FormData(e.target);try{const data={username:f.get('username'),password:f.get('password')};if(authMode==='register'){if(f.get('password')!==f.get('repeat'))throw Error('两次密码不一致');Object.assign(data,{name:f.get('name'),role:authRole});}await api('/auth/'+authMode,'POST',data);page='today';selectedChild='';await refresh();}catch(error){$('#auth-error').textContent=error.message;button.disabled=false}});}
function welcome(kicker,title,sub,action=''){return `<section class="welcome"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${sub}</p></div>${action}</section>`}
function empty(text,emoji='🌱'){return `<div class="empty"><span>${emoji}</span>${text}</div>`}
function render(){if(!state)return renderAuth();const nav=[['today','home',parent()?'孩子的习惯':'今日习惯'],['reviews','shield',parent()?'审核打卡':'打卡记录'],['shop','gift','心愿商店'],['orders','book','兑换记录'],['ledger','chart','积分明细'],['calendar','calendar','成长统计'],['family','leaf','我的家庭']];if(parent())nav.push(['manage','book','任务与奖励']);const title=nav.find(x=>x[0]===page)?.[2]||'成长花园';$('#app').innerHTML=`<div class="mobile-scrim ${menu?'open':''}" data-action="menu"></div><aside class="sidebar ${menu?'open':''}"><div class="brand"><div class="brand-mark">${icon('leaf')}</div><div><strong>小小成长家</strong><small>LITTLE HABIT GARDEN</small></div></div><div class="nav-label">${parent()?'家长端 · 陪伴每一步':'孩子端 · 每一天都在成长'}</div><nav class="nav" aria-label="主导航">${nav.map(([key,i,label])=>btn(`${icon(i)}${label}${key==='reviews'&&pending().length?`<span class="badge">${pending().length}</span>`:''}`,'nav',page===key?'active':'',`data-page="${key}" ${page===key?'aria-current="page"':''}`)).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-quote"><span>🌱</span><p>孩子记录，家长认可。<br>让成长有迹可循。</p></div>${btn(`${icon('shield')}账号设置`,'profile','parent-button')}${btn('退出登录','logout','parent-button')}</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${btn(icon('menu'),'menu','menu-toggle','aria-label="打开菜单"')}${icon('home')}成长花园 <span>/</span> <span>${title}</span></div><div class="topright">${parent()&&state.children.length?`<select id="child-select" aria-label="选择孩子">${state.children.map(c=>`<option value="${c.id}" ${child()?.id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}<button class="profile" data-action="profile"><span class="avatar">${esc(state.me.avatar)}</span><div>${esc(state.me.name)}<small>${parent()?'家长端':'孩子端'}</small></div></button></div></header>${page==='family'?familyPage():!child()?noChildPage():page==='today'?todayPage():page==='reviews'?reviewsPage():page==='shop'?shopPage():page==='orders'?ordersPage():page==='ledger'?ledgerPage():page==='calendar'?calendarPage():managePage()}<footer class="footer">${icon('leaf')} 用陪伴浇灌，让好习惯慢慢发芽 · 北京时间</footer></main>`;$('#child-select')?.addEventListener('change',async e=>{selectedChild=e.target.value;try{await refresh()}catch(err){toast(err.message)}});}
function noChildPage(){return `${welcome('GROW TOGETHER','先把家人连接起来 🌳','绑定孩子后，就能安排任务、审核打卡和管理奖励。')}<section class="panel lock-panel"><span>👨‍👩‍👧</span><h2>陪伴，从一次连接开始</h2><p>请孩子注册孩子端账号，在「我的家庭」生成绑定码。<br>孩子可以绑定多位家长，你也可以陪伴多个孩子。</p>${btn('输入孩子的绑定码','bind','primary')}</section>`}
function wallet(){return `<section class="wallet"><div class="wallet-title">✧ ${parent()?esc(child().name)+'的':'我的'}积分小金库</div><div class="wallet-value">${money().toLocaleString()}<span>积分</span></div><div class="coin-art">✦</div><div class="wallet-note">审核通过后，努力就会变成积分</div><div class="wallet-divider"></div><div class="wallet-bottom"><span>可兑换现金 ¥${money().toLocaleString()}</span>${btn('去商店 →','nav','text-button','data-page="shop"')}</div></section>`}
function todayPage(){const approved=records().filter(c=>c.day===state.day&&c.status==='approved').length;const marked=state.tasks.filter(t=>todayRecord(t.id)).length;return `${welcome('A LITTLE BETTER, EVERY DAY',`${esc(child().name)}，今天也一起加油 ☀️`,parent()?'认真看见每一份努力，及时送上你的认可。':'先记录完成的内容，再提交给家长审核，审核通过才计分。',parent()?btn(`${icon('plus')} 添加任务`,'add-task'):btn(`提交审核${drafts().length?'（'+drafts().length+'）':''}`,'submit-drafts','primary',drafts().length?'':'disabled'))}<div class="hero-grid"><section class="garden-banner"><div class="garden-copy"><span class="pill">🌱 我的习惯成长计划</span><h2>每一个好习惯，<br>都是一颗成长的种子。</h2><p>认真做完，诚实记录。每一步进步，都值得被看见。</p><div class="progress-row"><div class="progress-track"><i style="width:${state.tasks.length?marked/state.tasks.length*100:0}%"></i></div><span>今日已记录 ${marked} / ${state.tasks.length}</span></div></div>${garden}</section>${wallet()}</div><section class="stats">${[['☀️','今日入账','+'+state.stats.today_points,'积分'],['🌿','等待审核',pending().length,'项'],['🏅','累计通过',state.stats.approved,'次好习惯']].map(([i,l,n,u])=>`<div class="stat"><div class="stat-icon">${i}</div><div><div class="stat-label">${l}</div><div class="stat-number">${n}<small>${u}</small></div></div></div>`).join('')}</section><div class="review-schedule"><span>🕙 ${child().auto_submit?'22:00 自动提交已完成内容':'已关闭自动提交，请手动提交'}</span><span>🕦 23:30 未审核自动通过</span>${!parent()?btn('修改设置','profile','text-button'):''}</div><div class="content-grid"><section><div class="section-heading"><h2>每日任务 <small>${state.day} · 已通过 ${approved} 项</small></h2>${parent()?btn('管理任务 →','nav','text-button','data-page="manage"'):btn('查看记录 →','nav','text-button','data-page="reviews"')}</div><div class="tabs">${['全部习惯','学习成长','家务劳动','生活习惯'].map(f=>btn(f,'filter',filter===f?'selected':'',`data-filter="${f}"`)).join('')}</div><div class="habit-list">${state.tasks.filter(t=>filter==='全部习惯'||t.category===filter).map(taskRow).join('')||empty(parent()?'为孩子添加第一个成长任务吧。':'等待家长为你安排任务。')}</div></section><aside class="side-column"><div class="section-heading"><h2>小小心愿</h2>${btn('全部奖励 →','nav','text-button','data-page="shop"')}</div><div class="reward-box">${state.rewards.slice(0,3).map(r=>`<div class="reward-mini"><div class="reward-mini-icon">${esc(r.icon)}</div><div class="reward-mini-info"><strong>${esc(r.name)}</strong><small>${r.type==='cash'?'1 积分 = ¥1':r.cost+' 积分'}</small></div>${!parent()?btn('兑换','redeem','',`data-id="${r.id}"`):''}</div>`).join('')||empty('心愿商店等家长来布置','🎁')}<div class="cash-note">💛 兑换时扣分，家长负责兑现。<br>现金 1 积分 = 1 元，由家长自行支付。</div></div><div class="weekly"><h3>家人的陪伴 <span>${state.family.length} 位家长</span></h3>${state.family.length?state.family.map(p=>`<span class="family-chip">${esc(p.avatar)} ${esc(p.name)}</span>`).join(''):'<p>先在「我的家庭」邀请家长绑定。</p>'}<p>任意一位家长同意即可，积分只入账一次。</p></div></aside></div>`}
function taskRow(t){const c=todayRecord(t.id);return `<article class="habit ${c?.status==='approved'?'done':''}"><div class="habit-emoji">${esc(t.icon)}</div><div class="habit-info"><div class="habit-name">${esc(t.name)}</div><div class="habit-sub">${esc(t.note||t.category)}${c?` · ${statusLabel(c)}`:''}</div></div><span class="habit-points">+${c?.points??t.points} ✧</span>${parent()?`<span class="status ${c?.status||''}">${c?statusLabel(c):'未打卡'}</span>`:c?btn(c.status==='draft'?'撤销记录':statusLabel(c),'undo',`check-button ${c.status==='approved'?'done':''}`,`data-id="${c.id}" ${c.status!=='draft'?'disabled':''}`):btn('记录完成','check','check-button',`data-id="${t.id}"`)}</article>`}
function reviewsPage(){const list=records().filter(c=>reviewFilter==='all'||c.status===reviewFilter);return `${welcome('EVERY EFFORT DESERVES A RESPONSE',parent()?'审核孩子的努力 🌿':'我的打卡记录 🌿',parent()?'任意一位绑定家长审核即可。未处理的记录将在截止时间自动通过。':'只有已通过的打卡才会增加积分；未通过的记录不会计分。',!parent()&&drafts().length?btn(`提交全部待提交（${drafts().length}）`,'submit-drafts','primary'):'')}<div class="notice">23:30 前提交的记录，当天 23:30 自动审核；23:30 后提交的记录，次日 23:30 自动审核。<br>自动提交只处理已记录完成的任务。这里展示所有待处理记录，以及最近 30 天的已处理记录。</div><div class="tabs">${[['pending','待审核'],['draft','待提交'],['approved','已通过'],['rejected','未通过'],['all','全部']].map(([k,v])=>btn(v,'review-filter',reviewFilter===k?'selected':'',`data-filter="${k}"`)).join('')}</div><section class="panel review-list">${list.map(c=>`<article class="record"><div class="record-icon">${esc(c.icon)}</div><div class="record-info"><strong>${esc(c.task_name)} <span class="point-tag">+${c.points} 积分</span></strong><small>${c.day} · ${c.submission_mode==='auto'?'自动提交':c.submission_mode==='manual'?'主动提交':'尚未提交'}${c.review_deadline?' · 截止 '+fmt(c.review_deadline):''}</small>${c.note?`<p class="record-note">孩子的话：${esc(c.note)}</p>`:''}${c.review_reason?`<p class="record-note">审核说明：${esc(c.review_reason)}</p>`:''}${c.reviewed_at?`<small>${c.auto_approved?'系统自动审核':esc(c.reviewer_name||'家长')+'审核'} · ${fmt(c.reviewed_at)}</small>`:''}</div><span class="status ${c.status}">${statusLabel(c)}</span>${parent()&&c.status==='pending'?`<div class="actions">${btn('同意并加分','approve','primary',`data-id="${c.id}"`)}${btn('不通过','reject','outline',`data-id="${c.id}"`)}</div>`:!parent()&&c.status==='draft'?btn('撤销记录','undo','text-button',`data-id="${c.id}"`):''}</article>`).join('')||empty('这里还没有记录。','📋')}</section>`}
function shopPage(){return `${welcome('LITTLE WISHES, BIG MOTIVATION','心愿商店 🎁','用一点点努力，兑换一份属于自己的快乐。',parent()?btn('+ 添加奖励','add-reward'):'')}<div class="notice">可用积分 <strong>${money()}</strong> ✧　｜　现金 1 积分 = 1 元　·　兑换后由家长支付或兑现</div><div class="shop-grid">${state.rewards.map(r=>`<article class="reward-card"><div class="reward-visual">${esc(r.icon)}</div><h3>${esc(r.name)}</h3><p>${esc(r.note||'用努力兑换小小的美好')}</p><div class="reward-bottom"><span>✧ ${r.type==='cash'?'1 积分 / 元':r.cost+' 积分'}</span>${btn(parent()?'编辑奖励':'兑换心愿',parent()?'edit-reward':'redeem','primary',`data-id="${r.id}"`)}</div></article>`).join('')||empty(parent()?'添加冰淇淋、看电视或现金等奖励。':'家长还没有添加奖励，和家长聊聊你的心愿吧。','🎁')}</div>`}
function ordersPage(){return `${welcome('HAPPINESS IS ON THE WAY','兑换记录','兑换立即扣分；家长实际兑现后再确认。')}<div class="notice">现金由家长自行支付，网页不会自动转账。取消待兑现订单会自动退回积分。展示全部待兑现订单及最近 200 笔订单。</div><section class="panel">${state.orders.map(o=>`<div class="record"><div class="record-icon">${esc(o.icon)}</div><div class="record-info"><strong>${esc(o.title)}</strong><small>${fmt(o.created_at)} · ${o.cost} 积分${o.type==='cash'?` · 家长支付 ¥${o.cost}`:''}${o.handled_at?` · ${esc(o.handler_name||'家长')}处理于 ${fmt(o.handled_at)}`:''}</small></div><span class="status ${o.status}">${{pending:'待家长兑现',fulfilled:'已兑现',cancelled:'已取消并退分'}[o.status]}</span>${parent()&&o.status==='pending'?`<div class="actions">${btn(o.type==='cash'?'确认已支付':'确认已兑现','fulfill','primary',`data-id="${o.id}"`)}${btn('取消并退分','cancel-order','outline',`data-id="${o.id}"`)}</div>`:''}</div>`).join('')||empty('还没有兑换记录。','🎁')}</section>`}
function ledgerPage(){return `${welcome('EVERY EFFORT COUNTS','积分明细','积分由服务器记录，每一份付出都有迹可循。',parent()?btn('± 调整积分','adjust'):'')}<div class="hero-grid">${wallet()}<div class="notice">审核通过才加分，驳回不计分。<br>下方展示最近 200 笔流水，完整历史保存在 MySQL 数据库中。</div></div><section class="panel">${state.ledger.map(e=>`<div class="record"><div class="record-icon">${{checkin:'🌱',redeem:'🎁',adjust:'⭐',refund:'↩️'}[e.kind]}</div><div class="record-info"><strong>${esc(e.title)}</strong><small>${fmt(e.created_at)} · ${esc(e.actor_name||'系统')} · 余额 ${e.balance_after}</small></div><div class="amount ${e.amount<0?'negative':''}">${e.amount>0?'+':''}${e.amount}</div></div>`).join('')||empty('审核通过第一个打卡，记录第一份努力吧。','📒')}</section>`}
function familyPage(){return `${welcome('OUR LITTLE FAMILY','我的家庭 👨‍👩‍👧','一个孩子可以绑定多位家长，共同陪伴，每条打卡只计分一次。',btn(parent()?'绑定孩子':'生成家长绑定码',parent()?'bind':'invite','primary'))}<div class="notice">孩子生成一次性绑定码，交给家长输入。每个绑定码 24 小时内有效，使用一次后失效；绑定其他家长时再次生成。<br>绑定后的家长可以管理孩子的任务、积分和奖励，也可以审核打卡、确认兑现。</div><section class="panel"><h2>${parent()?'我陪伴的孩子': '陪伴我的家长'}</h2>${(parent()?state.children:state.family).map(p=>`<div class="record"><div class="record-icon">${esc(p.avatar)}</div><div class="record-info"><strong>${esc(p.name)}</strong><small>${parent()?'已绑定孩子账号':'已绑定家长账号'}</small></div>${parent()?btn('查看成长','select-child','outline',`data-id="${p.id}"`):''}</div>`).join('')||empty(parent()?'还没有绑定孩子。':'还没有绑定家长，请生成绑定码。','🏡')}</section>`}
function calendarPage(){if(!calendarData)return `${welcome('MY GROWTH CALENDAR','成长日历 📅','每一个颜色方块，都是一次认真的努力。')}${empty('正在加载成长记录…','🌱')}`;const childName=esc(child().name);return `${welcome('MY GROWTH CALENDAR',parent()?`${childName}的成长日历 📅`:'我的成长日历 📅','每一个方块都是一次认真的努力。鼠标悬停可以看到当天详情。')}${calendarHeatmap(calendarData.data)}<section class="panel"><h2>最近 30 天记录</h2><div class="history-list">${records().filter(c=>c.status==='approved').slice(0,20).map(c=>`<div class="history-item"><span class="history-date">${c.day}</span><span class="history-emoji">${esc(c.icon)}</span><span class="history-name">${esc(c.task_name)}</span><span class="history-points">+${c.points}</span></div>`).join('')||empty('还没有已通过的打卡记录。')}</div></section>`}
function managePage(){if(!parent())return todayPage();return `${welcome('GROW TOGETHER','任务与奖励管理 🌳',`为 ${esc(child().name)} 设置清晰、温柔的成长约定。`,btn('± 调整积分','adjust','primary'))}<div class="notice">每个任务每天可打卡一次。修改积分只影响以后的打卡；已记录的打卡和兑换保留原有积分。停用任务或奖励不会删除历史。</div><div class="settings-grid">${[['tasks','每日任务','add-task','edit-task','delete-task'],['rewards','心愿奖励','add-reward','edit-reward','delete-reward']].map(([key,label,add,edit,del])=>`<section class="panel admin-list"><div class="section-heading"><h2>${label}</h2>${btn('+ 添加',add,'text-button')}</div>${state[key].map(x=>`<div class="record"><div class="record-icon">${esc(x.icon)}</div><div class="record-info"><strong>${esc(x.name)}</strong><small>${key==='tasks'?`${esc(x.category)} · 每日 +${x.points} 积分`:x.type==='cash'?'现金 · 1 积分 = 1 元':x.cost+' 积分'}</small></div><div class="actions">${btn('编辑',edit,'text-button',`data-id="${x.id}"`)}${btn('停用',del,'text-button',`data-id="${x.id}"`)}</div></div>`).join('')||empty('点击添加，设置第一项内容。')}</section>`).join('')}</div>`}
const field=(label,name,value='',type='text',attrs='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const submit=(label='保存')=>`<button class="primary full" type="submit">${label}</button>`;
const emojiField=(value,category)=>{const groups=[];if(category&&emojiBank[category]){groups.push(['推荐 · '+category,emojiBank[category]]);}groups.push(['📚 学习成长',emojiBank['学习成长']],['🏠 家务劳动',emojiBank['家务劳动']],['🌱 生活习惯',emojiBank['生活习惯']],['🎁 奖励/礼物',emojiBank['奖励/礼物']],['⚽ 运动/活动',emojiBank['运动/活动']]);return `<div class="field"><label for="f-icon">选择图标，或输入喜欢的 emoji</label>${groups.map(([label,list])=>`<div class="emoji-group"><div class="emoji-group-label">${label}</div><div class="emoji-picker">${list.map(e=>`<button type="button" data-action="emoji" data-emoji="${e}" aria-label="选择 ${e}">${e}</button>`).join('')}</div></div>`).join('')}<input id="f-icon" name="icon" value="${esc(value)}" maxlength="16" required></div>`;};
function closeModal(){const el=focusBeforeModal;$('#modal-root').innerHTML='';document.body.style.overflow='';focusBeforeModal=null;el?.focus();}
function modal(title,body,onSubmit){focusBeforeModal=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><form id="modal-form">${body}<div id="form-error" class="error" role="alert"></div></form></section></div>`;document.body.style.overflow='hidden';$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');if(button?.disabled)return;if(button)button.disabled=true;try{await onSubmit(new FormData(e.target))}catch(error){if($('#form-error'))$('#form-error').textContent=error.message;else toast(error.message)}finally{if(button)button.disabled=false}});setTimeout(()=>$('#modal-root input, #modal-root select, #modal-root .primary, #modal-root .close')?.focus(),25);}
async function finish(path,method,body,message){await api(path,method,body);closeModal();await refresh();toast(message)}
function confirmModal(title,message,action,label='确认'){modal(title,`<p>${message}</p>${submit(label)}`,action)}
function editTask(taskId){const t=state.tasks.find(x=>x.id===taskId)||{name:'',icon:'📖',category:'学习成长',points:5,note:''};const base=`/children/${child().id}/tasks`;const isNew=!taskId;modal(isNew?'添加每日任务':'编辑每日任务',`${isNew?presetPickerHtml('✨ 快速选择预设任务',taskPresets,'task')+'<div class="preset-or">或者手动填写 ↓</div>':''}${field('任务名称','name',t.name,'text','required maxlength="60"')}${emojiField(t.icon,t.category)}<div class="field-row"><div class="field"><label for="f-category">任务分类</label><select name="category" id="f-category" data-action="category-change">${['学习成长','家务劳动','生活习惯'].map(c=>`<option ${t.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${field('审核通过后奖励积分','points',t.points,'number','required min="1" max="1000000" step="1"')}</div>${field('一句小鼓励','note',t.note||(isNew?randomEncouragement():''),'text','maxlength="200" placeholder="留空则不显示给孩子"')}<p>每日可打卡一次，审核通过才计分。修改不影响已打卡的记录。</p>${submit()}`,f=>finish(base+(taskId?'/'+taskId:''),taskId?'PUT':'POST',{name:f.get('name'),icon:f.get('icon'),category:f.get('category'),points:Number(f.get('points')),note:f.get('note')},'任务已保存 🌱'));}
function editReward(rewardId){const r=state.rewards.find(x=>x.id===rewardId)||{name:'',icon:'🎁',type:'reward',cost:20,note:''};const base=`/children/${child().id}/rewards`;const isNew=!rewardId;modal(isNew?'添加心愿奖励':'编辑心愿奖励',`${isNew?presetPickerHtml('✨ 快速选择预设奖励',rewardPresets,'reward')+'<div class="preset-or">或者手动填写 ↓</div>':''}${field('奖励名称','name',r.name,'text','required maxlength="60"')}${emojiField(r.icon,'奖励/礼物')}<div class="field-row"><div class="field"><label for="f-type">兑换类型</label><select name="type" id="f-type"><option value="reward" ${r.type==='reward'?'selected':''}>实物 / 活动</option><option value="cash" ${r.type==='cash'?'selected':''}>现金（1:1）</option></select></div>${field('所需积分 / 默认现金金额','cost',r.cost,'number','required min="1" max="1000000" step="1"')}</div>${field('奖励说明','note',r.note,'text','maxlength="200" placeholder="孩子看到会更期待"')}<p>现金兑换时可选择整数金额，始终按 1 积分 = 1 元扣分。</p>${submit()}`,f=>finish(base+(rewardId?'/'+rewardId:''),rewardId?'PUT':'POST',{name:f.get('name'),icon:f.get('icon'),type:f.get('type'),cost:Number(f.get('cost')),note:f.get('note')},'奖励已保存 🎁'));}
function profileModal(){modal('我的账号',`${field('昵称','name',state.me.name,'text','required maxlength="40"')}${emojiField(state.me.avatar)}${!parent()?`<label class="checkbox-line"><input type="checkbox" name="auto_submit" ${state.me.auto_submit?'checked':''}>每天 22:00 自动提交已完成内容</label><p>关闭后需要自己点击“提交审核”。23:30 未审核自动通过的规则仍然生效。</p>`:''}<p>账号：${esc(state.me.username)} · ${parent()?'家长端':'孩子端'}</p>${submit('保存设置')}${btn('修改密码','password','ghost','type="button"')}`,f=>finish('/profile','PATCH',{name:f.get('name'),avatar:f.get('icon'),...(!parent()?{auto_submit:f.has('auto_submit')}:{})},'账号设置已保存'));}
function approveModal(id,approve){const row=records().find(c=>c.id===id);modal(approve?'认可这份努力':'给孩子一点提醒',`<div class="modal-summary"><div class="big-emoji">${esc(row.icon)}</div><h3>${esc(row.task_name)}</h3><strong>${approve?'通过后 +'+row.points+' 积分':'本次不计分'}</strong></div>${field(approve?'鼓励的话（选填）':'不通过的原因','reason','','text',`maxlength="300" ${approve?'':'required'}`)}${submit(approve?'同意并计入积分':'确认不通过')}`,async f=>{const r=await api(`/checkins/${id}/review`,'POST',{approve,reason:f.get('reason')});closeModal();await refresh();toast(r.automatic?'已到截止时间，系统已自动通过':approve?'已通过审核，积分已入账 🌱':'已记录审核结果')});}
function redeemModal(id){const r=state.rewards.find(x=>x.id===id),requestKey=requestId();modal('兑换一个小心愿',`<div class="modal-summary"><div class="big-emoji">${esc(r.icon)}</div><h3>${esc(r.name)}</h3><strong>${r.type==='cash'?'1 积分 = 1 元':r.cost+' 积分'}</strong><p>可用 ${money()} 积分</p></div>${r.type==='cash'?field('现金金额 / 元','amount',r.cost,'number','required min="1" max="1000000" step="1"'):''}<p>确认后立即扣分，由家长支付或兑现。余额不足不能兑换。</p>${submit('确认兑换')}`,f=>finish(`/rewards/${id}/redeem`,'POST',{requestKey,...(r.type==='cash'?{amount:Number(f.get('amount'))}:{})},'已扣分，心愿等待家长兑现 🎁'));}
async function handle(action,el){const id=el.dataset.id;switch(action){
case 'auth-tab':authMode=el.dataset.mode;renderAuth();break;
case 'auth-role':{const form=$('#auth-form'),saved=new FormData(form);authRole=el.dataset.role;renderAuth();for(const [k,v] of saved){const input=$(`#auth-form [name="${k}"]`);if(input)input.value=v;}break;}
case 'menu':menu=!menu;render();break;
case 'nav':page=el.dataset.page;menu=false;render();window.scrollTo(0,0);break;
case 'filter':filter=el.dataset.filter;render();break;
case 'review-filter':reviewFilter=el.dataset.filter;render();break;
case 'close':closeModal();break;
case 'logout':confirmModal('退出登录？','退出后，下次需要输入账号和密码。平时直接关闭 App 或网页即可。',async()=>{await api('/auth/logout','POST',{});closeModal();state=null;selectedChild='';authMode='login';renderAuth();},'确认退出');break;
case 'retry-connection':await connect();break;
case 'profile':profileModal();break;
case 'password':modal('修改登录密码',`${field('当前密码','current','','password','required autocomplete="current-password"')}${field('新密码','password','','password','required minlength="8" maxlength="128" autocomplete="new-password"')}${field('确认新密码','repeat','','password','required minlength="8" maxlength="128" autocomplete="new-password"')}${submit('修改密码')}`,async f=>{if(f.get('password')!==f.get('repeat'))throw Error('两次密码不一致');await finish('/password','POST',{current:f.get('current'),password:f.get('password')},'密码已修改，其他设备需重新登录')});break;
case 'invite':{const r=await api('/family/invite','POST',{});modal('邀请家长陪伴你',`<p>请将下面的绑定码交给家长，在家长端的“我的家庭”输入。仅分享给你希望绑定的家长。</p><div class="invite-code">${esc(r.code)}</div><p>有效期至 ${fmt(r.expires_at)}，只能使用一次。生成新码后旧的未使用码失效。</p>${btn('复制绑定码','copy-code','primary full',`type="button" data-code="${r.code}"`)}`,()=>{});break;}
case 'copy-code':if(navigator.clipboard){await navigator.clipboard.writeText(el.dataset.code);toast('绑定码已复制')}else toast('请选中上方绑定码，手动复制');break;
case 'bind':modal('绑定孩子账号',`${field('孩子生成的绑定码','code','','text','required maxlength="16" minlength="16" placeholder="输入孩子端的 16 位绑定码"')}<p>绑定后可管理孩子的任务、审核打卡及兑现奖励。</p>${submit('确认绑定')}`,async f=>{const r=await api('/family/bind','POST',{code:f.get('code')});selectedChild=r.child_id;closeModal();page='today';await refresh();toast('绑定成功，一起陪伴成长 🌳')});break;
case 'select-child':selectedChild=id;page='today';await refresh();break;
case 'add-task':editTask();break;case 'edit-task':editTask(id);break;
case 'add-reward':editReward();break;case 'edit-reward':editReward(id);break;
case 'delete-task':case 'delete-reward':{const kind=action==='delete-task'?'tasks':'rewards',base=`/children/${child().id}/${kind}/${id}`;confirmModal('停用这项内容','停用后不再显示为新任务或奖励。已有打卡、审核、积分和兑换记录会保留。',()=>finish(base,'DELETE',{},'已停用'),'确认停用');break;}
case 'check':{const task=state.tasks.find(t=>t.id===id);modal('记录今天的完成',`<div class="modal-summary"><div class="big-emoji">${esc(task.icon)}</div><h3>${esc(task.name)}</h3><p>审核通过后获得 ${task.points} 积分</p></div>${quoteBubble()}${field('想对家长说的话（选填）','note','','text','maxlength="500" placeholder="例如：今天读完了一个故事"')}<p>记录完成后可主动提交；${child().auto_submit?'也会在 22:00 自动提交。':'你已关闭自动提交，请记得主动提交。'}请如实记录。</p>${submit('我已完成，保存记录')}`,f=>finish(`/tasks/${id}/checkin`,'POST',{note:f.get('note')},'已记录完成，审核通过后计分'));break;}
case 'undo':confirmModal('撤销待提交记录','尚未提交的内容可以撤销，撤销不影响积分。',()=>finish(`/checkins/${id}/draft`,'DELETE',{},'记录已撤销'),'确认撤销');break;
case 'submit-drafts':confirmModal('把努力交给家长看看',`将提交全部 ${drafts().length} 项待提交记录，审核通过后才获得积分。`,async()=>{const r=await api('/checkins/submit','POST',{});closeModal();reviewFilter='pending';await refresh();toast(`已提交 ${r.submitted} 项，等待家长审核`);},'提交审核');break;
case 'approve':approveModal(id,true);break;case 'reject':approveModal(id,false);break;
case 'redeem':redeemModal(id);break;
case 'fulfill':case 'cancel-order':{const order=state.orders.find(o=>o.id===id),cancel=action==='cancel-order';confirmModal(cancel?'取消并退回积分':order.type==='cash'?'确认现金已支付':'确认奖励已兑现',cancel?`取消后退回 ${order.cost} 积分，不会重复退款。`:order.type==='cash'?`请确认你已经向孩子支付 ¥${order.cost}。网页只记录支付状态，不会转账。`:`请确认已经兑现“${esc(order.title)}”。此操作不会再次扣分。`,()=>finish(`/orders/${id}/handle`,'POST',{action:cancel?'cancel':'fulfill'},cancel?'兑换已取消，积分已退回':'已记录兑现，收获一份快乐 💛'));break;}
case 'adjust':{const key=requestId(),path=`/children/${child().id}/adjust`;modal('调整成长积分',`<p>当前余额 ${money()} 积分。记录原因，及时鼓励，也温柔提醒。</p><div class="field-row"><div class="field"><label for="f-direction">调整方式</label><select name="direction" id="f-direction"><option value="1">奖励加分 ＋</option><option value="-1">提醒减分 −</option></select></div>${field('积分数量','amount',5,'number','required min="1" max="1000000" step="1"')}</div>${field('调整原因','reason','','text','required maxlength="100"')}${submit('确认调整')}`,f=>finish(path,'POST',{amount:Number(f.get('amount'))*Number(f.get('direction')),reason:f.get('reason'),requestKey:key},'积分已调整'));break;}
case 'use-preset':{const preset=JSON.parse(decodeURIComponent(el.dataset.preset));const kind=el.dataset.kind;const setv=(name,val)=>{const i=document.querySelector(`#modal-form [name="${name}"]`);if(i){i.value=val;i.dispatchEvent(new Event('change',{bubbles:true}));}};setv('name',preset.name);setv('icon',preset.icon);if(kind==='task'){setv('category',preset.category);setv('points',preset.points);if(preset.note)setv('note',preset.note);}else{setv('type',preset.type);setv('cost',preset.cost);if(preset.note)setv('note',preset.note);}toast(`已选择预设：${preset.name}`);break;}
case 'category-change':case 'emoji':{if(action==='emoji'){document.querySelector('#modal-form [name="icon"]').value=el.dataset.emoji;return;}const sel=el;const category=sel.value;const modal=document.querySelector('#modal-form');const oldGroups=modal?.querySelectorAll('.emoji-group');const iconInput=modal?.querySelector('[name="icon"]');if(oldGroups?.length&&iconInput){const current=iconInput.value;const recList=emojiBank[category]||[];const rest=Object.entries(emojiBank).filter(([k])=>k!==category);modal.innerHTML=modal.innerHTML.replace(/<div class="emoji-group"><div class="emoji-group-label">推荐.*?<\/div>[\s\S]*?<\/div><\/div>/g,'');const recHtml=recList.length?`<div class="emoji-group"><div class="emoji-group-label">✨ 推荐 · ${category}</div><div class="emoji-picker">${recList.map(e=>`<button type="button" data-action="emoji" data-emoji="${e}">${e}</button>`).join('')}</div></div>`:'';const allHtml=rest.map(([label,list])=>`<div class="emoji-group"><div class="emoji-group-label">${label}</div><div class="emoji-picker">${list.map(e=>`<button type="button" data-action="emoji" data-emoji="${e}">${e}</button>`).join('')}</div></div>`).join('');const pickerContainer=modal.querySelector('.field:last-of-type .emoji-group')?.parentElement;if(pickerContainer){pickerContainer.innerHTML=recHtml+allHtml;iconInput.value=current;}}break;}
}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;el.disabled=true;try{await handle(el.dataset.action,el)}catch(e){toast(e.message);if(e.status===401){state=null;closeModal();renderAuth()}}finally{el.disabled=false}});
document.addEventListener('keydown',e=>{const dialog=$('.modal');if(!dialog)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...dialog.querySelectorAll('button,input,select')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===items[0]){items.at(-1)?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){items[0]?.focus();e.preventDefault()}}});
document.addEventListener('change',async event=>{const el=event.target.closest('[data-action="category-change"]');if(!el)return;try{await handle('category-change',el)}catch(e){toast(e.message)}});
let syncing=false;
async function poll(){if(syncing||!state||document.hidden||$('.modal'))return;syncing=true;try{await refresh();$('#sync-error')?.remove()}catch(e){if(!$('#sync-error')){$('.topbar')?.insertAdjacentHTML('afterend',`<div class="notice" id="sync-error" role="alert">暂时无法同步：${esc(e.message)}。稍后自动重试。</div>`)}}finally{syncing=false}}
setInterval(poll,20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});
document.addEventListener('habit-resume',()=>{if(state)poll();else if(!$('#auth-form'))connect()});
document.addEventListener('habit-back',()=>{if($('.modal'))closeModal();else if(menu){menu=false;render()}else if(state&&page!=='today'){page='today';render()}});
async function connect(){
 $('#app').innerHTML='<div class="empty">正在连接成长花园…</div>';
 try{await refresh()}catch(e){$('#app').innerHTML=`<main class="empty"><span>🌱</span><h2>暂时连接不上成长花园</h2><p>${esc(e.message)}</p><p>连接恢复后会自动读取账号，不需要重新登录。</p>${btn('重新连接','retry-connection','primary')}</main>`}
}
connect();
